/// <summary>
/// MPJ_2864_CreditLimitBalance 03/11/2021
/// Service class to run the update and creation of new record
/// </summary>
public class METPopulateCustCreditLimitService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Checks if run in batch or not.
    /// </summary>
    public void processOperation()
    {
        BatchHeader                        batchHeader;
        SysOperationServiceController      controller;

        try
        {
            if (this.isExecutingInBatch())
            {
                if (!batchHeader)
                {
                    batchHeader = this.getCurrentBatchHeader();
                }

                // create new controller for the runtime task
                controller = new SysOperationServiceController(classStr(METPopulateCustCreditLimitService), methodStr(METPopulateCustCreditLimitService, run));
                
                batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
            }
            else
            {
                this.run();
            }

            if(batchHeader)
            {
                // save the batchheader if it has been created
                batchHeader.save();
            }
            
        }
        catch
        {
            info ("@MET:PopulateCustCreditErrorHandler");
        }

    }

    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Creates / updates the records
    /// </summary>
    public void run()
    {
        CustTable           custTable;
        METCustCreditLimit  metCustCreditLimit;
        METCustTable        metCustTable;
        AmountMST           balance;

        while select CreditMax, AccountNum from custTable
        {
            metCustCreditLimit = metCustCreditLimit::find(custTable.AccountNum, true);
            metCustTable       = metCustTable::find(custTable.AccountNum);
            balance            = this.getBalance(custTable.AccountNum);

            if (metCustCreditLimit)
            {
                ttsbegin;
                metCustCreditLimit.FrozenBalance    = metCustTable.FrozenBalance;
                metCustCreditLimit.ArrearsFlag      = metCustTable.ArrearsFlag;
                metCustCreditLimit.Balance          = balance;
                metCustCreditLimit.CreditLimit      = custTable.CreditMax;
                metCustCreditLimit.update();
                ttscommit;
            }
            else
            {
                metCustCreditLimit.AccountNum       = custTable.AccountNum;
                metCustCreditLimit.FrozenBalance    = metCustTable.FrozenBalance;
                metCustCreditLimit.ArrearsFlag      = metCustTable.ArrearsFlag;
                metCustCreditLimit.Balance          = balance;
                metCustCreditLimit.CreditLimit      = custTable.CreditMax;
                metCustCreditLimit.insert();
            }
        }
    }

    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Gets total AmountMST (Balance)
    /// </summary>
    /// <param name = "_AccountNum">Cust account num</param>
    /// <returns>total amount mst</returns>
    public AmountMST getBalance(AccountNum _AccountNum)
    {
        CustTrans custTrans;

        select sum(AmountMST) from custTrans
            where custTrans.AccountNum == _AccountNum;

        return custTrans.AmountMST;
    }
